script:
const user = frappe.session.user_fullname || frappe.session.user || "Guest";
    const hour = new Date().getHours();

    let text = "";
    let emoji = "";

    if (hour < 12) {
        text = "Good Morning";
        emoji = "🌱🌤️";
    } else if (hour < 17) {
        text = "Good Afternoon";
        emoji = "☀️";
    } else if (hour < 20) {
        text = "Good Evening";
        emoji = "🌕";
    } else {
        text = "Goodnight";
        emoji = "🌛🛏️";
    }
    root_element.querySelector('#greeting').textContent = `${text} ${emoji}`;
    root_element.querySelector('#username').textContent = `${user}`;

